function Copy({row,number,heading,source}){return <div className="study-copy" data-reveal>{number&&<span className="study-number">{number}</span>}<h3>{heading||row[1]}</h3><p>{source&&<><strong>{row[0]}.</strong> </>}{heading&&heading!==row[1]?row[1]+'. ':''}{row[2]}</p></div>}
