if(index===5)body=<div className="newcomer-composition"><div className="menu-illustration" data-reveal><div className="menu-sheet"><span>CAMPUS CAFÉ</span><div>Tea <b>₹ ?</b></div><div>Lunch <b>₹ ?</b></div><div>Snack <b>₹ ?</b></div><small>Familiar prices can support reconstruction</small></div><div className="newcomer-stamp">NEW<br/>TO CAMPUS</div></div><div className="editorial-list">{r.map((row,i)=><Copy key={i} row={row}/>)}</div></div>;
