if(index===9)body=<div className="procedure-composition"><div className="prep-row" data-reveal><span className="phase-number">01</span><Copy row={r[0]}/></div><div className="week-row" data-reveal><span className="phase-number">02</span><div><h3 className="phase-title">Monday–Sunday · Recorded spending</h3><div className="week-days">{['MON','TUE','WED','THU','FRI','SAT','SUN'].map((day,i)=><div key={day}><span>{day}</span><b>{i+1}</b></div>)}</div><p>{r[1][2]}</p></div></div><div className="test-row" data-reveal><span className="phase-number">03</span><div><h3>Monday · 6 pm recall</h3><p>{r[2][2]}</p></div><span className="tuesday-seal">MON</span></div></div>;
